# SPDX-License-Identifier: Apache-2.0
<#.SYNOPSIS
Compares D-09 records semantically, disregarding JSON property and list-response ordering.
#>
[CmdletBinding(SupportsShouldProcess)]
param()
$ErrorActionPreference = 'Stop'
$root = 'docs/receipts/hv'
if (-not $PSCmdlet.ShouldProcess($root, 'Save semantic D-09 comparison')) { return }
$differences = [Collections.Generic.List[object]]::new()
function Compare-HvTree {
    <#.SYNOPSIS
    Walks JSON values and reports leaf differences without depending on property order.
    #>
    param([object]$Before,[object]$After,[string]$Location)
    if ($Before -is [System.Collections.IDictionary] -and $After -is [System.Collections.IDictionary]) {
        foreach ($key in @(@($Before.Keys)+@($After.Keys) | Sort-Object -Unique)) { Compare-HvTree $Before[$key] $After[$key] "$Location.$key" }
    } elseif ($Before -is [array] -and $After -is [array]) {
        if ($Before.Count -ne $After.Count) { $differences.Add([pscustomobject]@{Path="$Location.Count";Before=$Before.Count;After=$After.Count}) }
        for ($i=0;$i -lt [Math]::Max($Before.Count,$After.Count);$i++) { Compare-HvTree $Before[$i] $After[$i] "$Location[$i]" }
    } elseif (($Before | ConvertTo-Json -Depth 100 -Compress) -cne ($After | ConvertTo-Json -Depth 100 -Compress)) {
        $differences.Add([pscustomobject]@{Path=$Location;Before=$Before;After=$After})
    }
}
$ids = @('FR-MCP-HOSTILEREVIEW-002','FR-MCP-HOSTILEREVIEW-003','TEST-MCP-HOSTILEREVIEW-002','TEST-MCP-HOSTILEREVIEW-003','FR-MCP-SESSIONLIFE-004','FR-MCP-SESSIONLIFE-005','TEST-MCP-SESSIONLIFE-002')
$recordCount=0
$edgeCount=0
foreach ($kind in @('fr','tr','test','mappings')) {
    $old=(Get-Content -Raw "$root/hv-r2-store-requirements-$kind.json" | ConvertFrom-Json -AsHashtable -Depth 100).items
    $current=(Get-Content -Raw "$root/hv-r3-store-requirements-$kind.json" | ConvertFrom-Json -AsHashtable -Depth 100).items
    if ($kind -eq 'mappings') {
        $old=@($old | Where-Object { $_.frId -in $ids } | Sort-Object frId,trId,testId)
        $current=@($current | Where-Object { $_.frId -in $ids } | Sort-Object frId,trId,testId)
        $edgeCount=$current.Count
        Compare-HvTree $old $current mappings
    } else {
        foreach ($record in @($current | Where-Object { $_.id -in $ids })) {
            $recordCount++
            Compare-HvTree @($old | Where-Object { $_.id -eq $record.id })[0] $record $record.id
        }
    }
}
$report=[pscustomobject]@{TimestampUtc=[DateTimeOffset]::UtcNow.ToString('o');RecordCount=$recordCount;MappingEdges=$edgeCount;DifferenceCount=$differences.Count;Differences=$differences}
$report | ConvertTo-Json -Depth 100 | Set-Content "$root/hv-r3-d09-semantic-diff.json"
$report | ConvertTo-Json -Depth 100

