# SPDX-License-Identifier: Apache-2.0
<# .SYNOPSIS
Checks reviewer receipts, script analysis, secret redaction and unchanged reviewed source without exposing credentials.
#>
[CmdletBinding(SupportsShouldProcess)]
param([ValidateSet('Analyze','Scan')][string]$Mode='Analyze')
$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot
if (-not $PSCmdlet.ShouldProcess($root, 'Write final reviewer evidence checks')) { return }
switch ($Mode) {
    'Analyze' {
        $results = @()
        foreach ($file in Get-ChildItem -LiteralPath $root -Filter 'hv-r3-*.ps1' -File) {
            $tokens=$null; $errors=$null
            [void][Management.Automation.Language.Parser]::ParseFile($file.FullName,[ref]$tokens,[ref]$errors)
            $diagnostics=@(Invoke-ScriptAnalyzer -Path $file.FullName -Severity Warning,Error)
            $results += [pscustomobject]@{ File=$file.Name; ParserErrors=$errors.Count; AnalyzerWarningsOrErrors=$diagnostics.Count; Diagnostics=@($diagnostics | ForEach-Object { "$($_.RuleName):$($_.Line):$($_.Message)" }); ApacheHeader=([IO.File]::ReadLines($file.FullName) | Select-Object -First 1) -ceq '# SPDX-License-Identifier: Apache-2.0' }
        }
        $results | ConvertTo-Json -Depth 10 | Set-Content "$root/hv-r3-final-script-analysis.json"
        $bad=@($results | Where-Object { $_.ParserErrors -or $_.AnalyzerWarningsOrErrors -or -not $_.ApacheHeader })
        [pscustomobject]@{ Scripts=$results.Count; Failing=$bad.Count; Details=$bad } | ConvertTo-Json -Depth 10
        if ($bad.Count) { throw 'Reviewer script checks failed.' }
    }
    'Scan' {
        $marker=[IO.File]::ReadAllText('/home/sharpninja/github/McpServer/AGENTS-README-FIRST.yaml')
        $keys=@([regex]::Matches($marker,'(?im)^apiKey:\s*([^\r\n]+)') | ForEach-Object { $_.Groups[1].Value.Trim().Trim('"',"'") } | Where-Object { $_.Length -ge 20 })
        $files=@(Get-ChildItem -LiteralPath $root -File | Where-Object { $_.Name -like 'hv-r3-*' -or $_.Name -like '*amendment1-r3-20261018T011809*' -or $_.Name -like '20261018T011809-amendment1-r3*' })
        $found=[Collections.Generic.List[object]]::new()
        foreach ($file in $files) {
            $text=[IO.File]::ReadAllText($file.FullName)
            foreach ($key in $keys) { if ($text.Contains($key)) { $found.Add([pscustomobject]@{ File=$file.Name; Kind='known marker key' }) } }
            if ([regex]::IsMatch($text,'(?i)(?:api[-_]?key|X-Api-Key)\s*[:=]\s*["'']?[A-Za-z0-9_./+\-=]{20,}')) { $found.Add([pscustomobject]@{ File=$file.Name; Kind='API key assignment pattern' }) }
        }
        $status=(& git status --short | Out-String)
        $statusExit=$LASTEXITCODE
        $head=(& git rev-parse HEAD | Out-String).Trim()
        $headExit=$LASTEXITCODE
        $sourceDiff=(& git diff 36783b79 HEAD -- src plugins/core tests | Out-String)
        $diffExit=$LASTEXITCODE
        $check=[ordered]@{ TimestampUtc=[DateTimeOffset]::UtcNow.ToString('o'); TimestampLocal=[DateTimeOffset]::Now.ToString('s'); ScannedFiles=$files.Count; SecretFindingCount=$found.Count; Findings=$found; HeadSha=$head; HeadExit=$headExit; GitStatus=$status; GitStatusExit=$statusExit; BaseSourceDiffEmpty=[string]::IsNullOrWhiteSpace($sourceDiff); BaseSourceDiffExit=$diffExit }
        $check | ConvertTo-Json -Depth 10 | Set-Content "$root/hv-r3-final-hygiene.json"
        [pscustomobject]@{ TimestampLocal=$check.TimestampLocal; ScannedFiles=$files.Count; SecretFindingCount=$found.Count; HeadSha=$head; BaseSourceDiffEmpty=$check.BaseSourceDiffEmpty; ExitCodes=@($statusExit,$headExit,$diffExit) } | ConvertTo-Json
        if ($found.Count -or $head -ne '9e6822246e0e13f51612c638bc72d148954ccc18' -or -not $check.BaseSourceDiffEmpty) { throw 'Final hygiene check failed; secrets are never printed.' }
    }
}

